 {section==='Team members'&&isAdmin&&<><div className="notice"><ShieldCheck size={16}/><span>Only admins can add, suspend, remove, or restrict team members. Members can work on their assigned leads. Invitations grant membership when the matching account signs in. This preview’s hosting access is still owner-only.</span></div><div className="team-grid">{data.members.map(m=>{const r=report.members.find(x=>x.memberId===m.id);return <div className="card member-card" key={m.id}><div className="member-head"><Avatar name={m.name} large/><div style={{flex:1}}><h3>{m.name}</h3><div className="company-sub" style={{marginTop:7}}>{m.email}</div></div></div><div style={{display:'flex',gap:8,marginTop:18}}><span className="status">{m.role==='admin'?'Admin':'Member'}</span><span className={`status ${m.status==='active'?'Replied':m.status==='invited'?'Qualified':m.status}`}>{m.status==='active'?'Active':m.status==='invited'?'Invited':m.status==='suspended'?'Suspended':'Removed'}</span></div><div className="member-stats"><span><strong>{data.leads.filter(l=>l.ownerId===m.id).length}</strong>Assigned leads</span><span><strong>{r?.sent||0}</strong>Outreach logged</span><span><strong>{r?.replies||0}</strong>Replies</span></div>{m.role==='member'&&<MemberControls member={m} onAction={mutate} disabled={busy}/>}</div>})}</div></>}
 {section==='Reports'&&allowed.reports&&<><div className="kpi-grid">{kpis.map(k=><div className="card kpi" key={k.label}><div className="kpi-top">{k.label}<span className="kpi-icon"><k.icon size={15}/></span></div><div className="kpi-number">{typeof k.value==='number'?fmt(k.value):k.value}</div><div className="kpi-bottom">{k.caption}</div></div>)}</div><div className="card" style={{marginBottom:23}}><div className="card-heading"><div><h2>{period==='week'?'Weekly':'Monthly'} outreach report</h2><p>{report.label} · Displayed in Asia/Karachi</p></div><CalendarDays size={17} className="muted"/></div><div className="chart-legend"><span><i className="legend-dot"/>Outreach logged</span><span><i className="legend-dot green"/>Replies</span></div><Chart daily={report.daily}/></div><div className="card"><div className="card-heading" style={{paddingBottom:22}}><h2>{isAdmin?'Team performance':'Your performance'}</h2><span className="small muted">{period==='week'?'Last 7 days':'Last 30 days'}</span></div><div className="table-wrap"><table><thead><tr><th>Team member</th><th>New leads assigned</th><th>Outreach logged</th><th>Replies</th><th>Reply rate</th></tr></thead><tbody>{report.members.filter(m=>isAdmin||m.memberId===member?.id).map(m=><tr key={m.memberId}><td><div className="lead-cell"><Avatar name={m.name}/><span className="company-name">{m.name}</span></div></td><td>{m.leads}</td><td>{m.sent}</td><td>{m.replies}</td><td>{m.replyRate.toFixed(1)}%</td></tr>)}</tbody></table></div></div><p className="range-note">Rolling 7 or 30 day periods. Drafts do not count as outreach. Reply rate is the share of contacted leads with a subsequent recorded reply during the same period. Until provider integration, activity is recorded by your team.</p></>}
 {section==='Social accounts'&&allowed.socialAccounts&&<><div className="notice"><Link2 size={16}/><span>Save your profile links now. Live connection requires provider OAuth and approved permissions. Instagram and Facebook are the first planned integrations.</span></div><div className="connections-grid">{platforms.slice(0,4).map(p=>{const a=displayData.accounts.find(a=>a.platform===p&&a.memberId===member?.id);return <div className="card connection-card" key={p}><PlatformBadge platform={p}/><h3>{p}</h3><p>{p==='Instagram'?'Professional accounts. Official messaging supports eligible conversations initiated by the recipient.':p==='Facebook'?'Facebook Pages. Messaging requires approved permissions and an eligible conversation.':p==='LinkedIn'?'Save LinkedIn profile links and record outreach. Broader API access requires partner approval.':'Search and messaging need a developer app, authorized access, and provider credits.'}</p>{a&&<div className="small" style={{marginBottom:15,color:'#8a7ba4'}}>{a.handle} · Profile saved</div>}<div className="connection-status"><span className="status Qualified">Setup required</span><button className="btn text" style={{fontSize:11}} onClick={()=>setModal(`account:${p}`)}>{a?'Edit profile':'Add profile'}<Plus size={12}/></button></div></div>})}</div></>}
 {section==='Settings'&&<div className="card settings-card"><h2>Workspace preferences</h2><div className="settings-row"><div><h3>Workspace</h3><p>{demo?'Highlevel workspace · Sample data':data.workspace?.name}</p></div><span className="status">{demo?'Demo':'Live'}</span></div><div className="settings-row"><div><h3>Your account</h3><p>{demo?member?.email:user?.email}<br/>{isAdmin?'Administrator':'Team member'}</p></div>{!demo&&<a className="btn" href="/signout-with-chatgpt?return_to=/" target="_top"><LogOut size={12}/>Sign out</a>}</div><div className="settings-row"><div><h3>Explore the workspace</h3><p>Sample data is separate from your saved records.</p></div><button className="btn" onClick={()=>{if(demo)startLive();else{setData(createDemoState());setDemo(true);setViewRole('admin');setThread(null);setSelected(null);setModal(null)}}}>{demo?'Use live workspace':'Open demo'}</button></div>{demo&&<div className="settings-row"><div><h3>Preview team access</h3><p>Try the interface as an admin or a team member.</p></div><select className="select" aria-label="Demo role" value={viewRole} onChange={e=>setViewRole(e.target.value as 'admin'|'member')}><option value="admin">Admin preview</option><option value="member">Member preview</option></select></div>}<div className="settings-row"><div><h3>Notifications</h3><p>In-app updates for recorded replies. Email notifications are planned.</p></div><span className="status Replied">In-app enabled</span></div><div className="settings-row"><div><h3>Hosting access</h3><p>This first version is private to you. Team access needs a separate hosting access change.</p></div><ShieldCheck size={20} className="muted"/></div></div>}
